import{_ as a}from"./plugin-vue_export-helper-c27b6911.js";import{o as e,c as s,f as n}from"./app-36705845.js";const i={},d=n(`<h1 id="git-极速教程" tabindex="-1"><a class="header-anchor" href="#git-极速教程" aria-hidden="true">#</a> Git 极速教程</h1><h2 id="理解-git-代码时光机" tabindex="-1"><a class="header-anchor" href="#理解-git-代码时光机" aria-hidden="true">#</a> 理解 Git：代码时光机</h2><p>你可以把 Git 想象成一个很严肃但很靠谱的“代码存档管理员”：</p><ul><li>你写代码，它在旁边看着。</li><li>你说“这版不错，存一下”，它就给你拍照留档。</li><li>你哪天把项目改炸了，它会淡定地说：“别慌，上一个存档还在。”</li><li>别人做了一些修改，没问题，它会帮你合并，有冲突时，它会问你：“看看你们俩谁的对，还是需要整合处理一下”</li></ul><p>简单来说，一段代码，你先编写了一下，编译通过了，你觉得看起来不错，那么你可以给这个软件起个版本号，比如v0.1 接下来，你觉得功能不够，你的朋友帮忙补充了一些，那么现在版本是v0.2 忽然你发现原先编写的某些功能不正常了，那么有可能是v0.2版引入了一个bug。 于是你需要回退到之前的版本，并比较修改了哪些部分，这个过程就是在进行版本管理。</p><p>Git 最核心的用法，其实就三句话：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> <span class="token function">add</span> <span class="token builtin class-name">.</span>
<span class="token function">git</span> commit <span class="token parameter variable">-m</span> <span class="token string">&quot;写清楚这次改了啥&quot;</span>
<span class="token function">git</span> push
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>翻译过来就是：</p><ol><li><code>git add .</code>：把当前改动记下来，这个文件要git处理了。</li><li><code>git commit -m &quot;...&quot;</code>：生成一个正式存档版本，并写上了备注信息。</li><li><code>git push</code>：把本地存档上传到远程仓库，比如 GitHub。</li></ol><h2 id="git-的三大现场" tabindex="-1"><a class="header-anchor" href="#git-的三大现场" aria-hidden="true">#</a> Git 的三大现场</h2><p>Git 里最常见的三个地方：</p><ol><li>工作区：你电脑里正在修改的文件，还只是“我改了”，Git 已经看见了，但还没准备保存。</li><li>暂存区：这次准备提交的改动清单。<code>git add</code> 就是在说：“这些改动我要打包成一个版本。”</li><li>仓库：已经正式保存下来的版本历史。<code>git commit</code> 之后，这次改动才算真正进了 Git 的档案库。</li></ol><p>流程大概是这样：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>写代码 -<span class="token operator">&gt;</span> <span class="token function">git</span> <span class="token function">add</span> -<span class="token operator">&gt;</span> <span class="token function">git</span> commit -<span class="token operator">&gt;</span> <span class="token function">git</span> push
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>只要记住这条流水线，你就已经不是 Git 小白，而是“刚拿到驾照的版本管理员”。</p><h2 id="常用命令速查" tabindex="-1"><a class="header-anchor" href="#常用命令速查" aria-hidden="true">#</a> 常用命令速查</h2><h3 id="查看现在乱不乱" tabindex="-1"><a class="header-anchor" href="#查看现在乱不乱" aria-hidden="true">#</a> 查看现在乱不乱</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> status
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>这个命令非常重要。它会告诉你：</p><ul><li>哪些文件改了。</li><li>哪些文件还没加入暂存区。</li><li>当前分支有没有领先或落后远程仓库。</li></ul><p>一句话：不知道发生了什么，就先 <code>git status</code>，看看现在工作区，暂存区都是啥样。</p><h3 id="把改动加入暂存区" tabindex="-1"><a class="header-anchor" href="#把改动加入暂存区" aria-hidden="true">#</a> 把改动加入暂存区</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> <span class="token function">add</span> 文件名
<span class="token function">git</span> <span class="token function">add</span> <span class="token builtin class-name">.</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><code>git add 文件名</code> 表示只添加某个文件。</p><p><code>git add .</code> 表示把当前目录下所有改动都添加进去。它很方便，但也很豪爽，可能把你不想提交的东西也塞进去，所以用之前最好先 <code>git status</code> 看一眼。</p><h3 id="提交一次存档" tabindex="-1"><a class="header-anchor" href="#提交一次存档" aria-hidden="true">#</a> 提交一次存档</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> commit <span class="token parameter variable">-m</span> <span class="token string">&quot;完成登录功能&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>提交信息不要写成：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> commit <span class="token parameter variable">-m</span> <span class="token string">&quot;改了一点东西&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>这样未来的你看了只会一脸懵逼，不知道改了啥。</p><p>推荐写清楚一点：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> commit <span class="token parameter variable">-m</span> <span class="token string">&quot;修复登录按钮无法点击的问题&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h2 id="和远程仓库打交道" tabindex="-1"><a class="header-anchor" href="#和远程仓库打交道" aria-hidden="true">#</a> 和远程仓库打交道</h2><h3 id="第一次克隆项目" tabindex="-1"><a class="header-anchor" href="#第一次克隆项目" aria-hidden="true">#</a> 第一次克隆项目</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> clone 仓库地址
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>意思是：把远程仓库完整复制到本地。</p><h3 id="拉取别人最新的代码" tabindex="-1"><a class="header-anchor" href="#拉取别人最新的代码" aria-hidden="true">#</a> 拉取别人最新的代码</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> pull
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>意思是：把远程仓库的新内容同步到本地。</p><p>多人合作时，开始写代码前先 <code>git pull</code>，让别人的改动先同步到你的机器上，让大家避免鸡同鸭讲。</p><h3 id="上传自己的提交" tabindex="-1"><a class="header-anchor" href="#上传自己的提交" aria-hidden="true">#</a> 上传自己的提交</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> push
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>意思是：把你的本地提交推到远程仓库。</p><p>如果 <code>commit</code> 是本地存档，那么 <code>push</code> 就是把存档发到云端，告诉大家：“朋友们，我更新了。”</p><h2 id="分支-平行宇宙实验室" tabindex="-1"><a class="header-anchor" href="#分支-平行宇宙实验室" aria-hidden="true">#</a> 分支：平行宇宙实验室</h2><p>分支可以理解为“开一个平行宇宙”。你可以在里面大胆实验，改炸了也不会立刻污染主线。</p><h3 id="查看分支" tabindex="-1"><a class="header-anchor" href="#查看分支" aria-hidden="true">#</a> 查看分支</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> branch
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="创建并切换到新分支" tabindex="-1"><a class="header-anchor" href="#创建并切换到新分支" aria-hidden="true">#</a> 创建并切换到新分支</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> checkout <span class="token parameter variable">-b</span> feature-login
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>或者新版 Git 可以写：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> switch <span class="token parameter variable">-c</span> feature-login
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>分支名建议写得有意义，比如：</p><ul><li><code>feature-login</code>：开发登录功能。</li><li><code>fix-header-style</code>：修复头部样式。</li><li><code>docs-git-guide</code>：修改 Git 文档。</li></ul><p>不要叫 <code>newnewnew-final-v2</code>，这不是分支名，这是人类精神状态报告。</p><h3 id="切换分支" tabindex="-1"><a class="header-anchor" href="#切换分支" aria-hidden="true">#</a> 切换分支</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> switch main
<span class="token function">git</span> switch feature-login
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>切换分支前最好先 <code>git status</code>，确认没有未处理的改动，不然 Git 可能会拦住你：“你先把手里的锅放下，再去隔壁厨房。”</p><h2 id="合并分支" tabindex="-1"><a class="header-anchor" href="#合并分支" aria-hidden="true">#</a> 合并分支</h2><p>当你的分支功能写完了，可以切回主分支并合并：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> switch main
<span class="token function">git</span> pull
<span class="token function">git</span> merge feature-login
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>意思是：</p><ol><li>回到主分支。</li><li>先同步最新代码。</li><li>把功能分支合进来。</li></ol><p>如果多人合作，更常见的做法是提交 Pull Request，让别人帮你看看代码有没有坑。</p><h2 id="冲突-git-的家庭伦理剧" tabindex="-1"><a class="header-anchor" href="#冲突-git-的家庭伦理剧" aria-hidden="true">#</a> 冲突：Git 的家庭伦理剧</h2><p>如果两个人改了同一个地方，Git 不知道该听谁的，就会产生冲突。</p><p>冲突文件里可能出现这种东西：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>  &lt;&lt;&lt;&lt;&lt;&lt;&lt; HEAD
  你的版本
  =======
  别人的版本
  &gt;&gt;&gt;&gt;&gt;&gt;&gt; branch-name
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>别怕，这不是乱码，这是 Git 在说：“你俩自己商量，我不背锅。”</p><p>解决方法：</p><ol><li>打开冲突文件。</li><li>手动决定保留哪部分内容。</li><li>删除 <code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code>、<code>=======</code>、<code>&gt;&gt;&gt;&gt;&gt;&gt;&gt;</code> 这些标记。</li><li>重新提交。</li></ol><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> <span class="token function">add</span> <span class="token builtin class-name">.</span>
<span class="token function">git</span> commit <span class="token parameter variable">-m</span> <span class="token string">&quot;解决合并冲突&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="后悔药-查看历史和回退" tabindex="-1"><a class="header-anchor" href="#后悔药-查看历史和回退" aria-hidden="true">#</a> 后悔药：查看历史和回退</h2><h3 id="查看提交历史" tabindex="-1"><a class="header-anchor" href="#查看提交历史" aria-hidden="true">#</a> 查看提交历史</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> log
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>如果嫌它太长，可以用：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> log <span class="token parameter variable">--oneline</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="查看某个文件改了什么" tabindex="-1"><a class="header-anchor" href="#查看某个文件改了什么" aria-hidden="true">#</a> 查看某个文件改了什么</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> <span class="token function">diff</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><code>git diff</code> 会显示你还没提交的改动。它像一个冷静的朋友，帮你指出：“你刚才确实动了这里，别装没看见。”</p><h3 id="撤销还没提交的改动" tabindex="-1"><a class="header-anchor" href="#撤销还没提交的改动" aria-hidden="true">#</a> 撤销还没提交的改动</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> restore 文件名
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>注意：这个命令会丢掉文件当前未提交的修改。用之前请确认你真的不要了，不然它会像橡皮擦一样干脆。</p><h2 id="新手推荐工作流" tabindex="-1"><a class="header-anchor" href="#新手推荐工作流" aria-hidden="true">#</a> 新手推荐工作流</h2><p>日常使用 Git，可以按这个顺序来：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> pull
<span class="token function">git</span> status
<span class="token function">git</span> switch <span class="token parameter variable">-c</span> my-task

<span class="token comment"># 写代码，改文档，快乐施工</span>

<span class="token function">git</span> status
<span class="token function">git</span> <span class="token function">add</span> <span class="token builtin class-name">.</span>
<span class="token function">git</span> commit <span class="token parameter variable">-m</span> <span class="token string">&quot;说明这次完成了什么&quot;</span>
<span class="token function">git</span> push
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果你只记一套流程，就记这个。</p><h2 id="最后总结" tabindex="-1"><a class="header-anchor" href="#最后总结" aria-hidden="true">#</a> 最后总结</h2><p>Git 不神秘，它主要做三件事：</p><ol><li>记录历史：<code>git add</code> + <code>git commit</code></li><li>同步代码：<code>git pull</code> + <code>git push</code></li><li>管理实验：<code>git branch</code> + <code>git switch</code> + <code>git merge</code></li></ol><p>初学时别追求把 Git 的十八般兵器一次学完。先会 <code>status</code>、<code>add</code>、<code>commit</code>、<code>pull</code>、<code>push</code>、<code>switch</code>，你就已经能在大多数项目里正常生存。</p><p>剩下的高级操作，等你真的遇到问题再学。Git 就像厨房刀具：先会切菜就行，不必第一天就练蒙眼雕萝卜。</p>`,92),l=[d];function t(c,r){return e(),s("div",null,l)}const u=a(i,[["render",t],["__file","git.html.vue"]]);export{u as default};
